return array[pivotIndex]

// If the k-th smallest element is in the left partition, recursively call quickSelect on the left partition
else if position > k:
return quickSelect(array, low, pivotIndex - 1, k)

// If the k-th smallest element is in the right partition, recursively call quickSelect on the right partition
else:
return quickSelect(array, pivotIndex + 1, high, k - position)

