#include <iostream>
#include <vector>
using namespace std;

int main() {
    // Read input and print output
    int n;
    cin>>n;
    vector<int> arr(n);
    for(int i=0;i<n;i++) cin>>arr[i];

    for(int i=0;i<n-1;i++){
        for(int j=0;j<n-i-1;j++){
            if(arr[j]>arr[j+1]) swap(arr[i],arr[i+1]);
        }
    }

    for(int x: arr) cout<<x<<" ";
    return 0;
}

